#include "stdlib/ml/strided/dkmeans_compute_inertia.h"
#include "stdlib/strided/base/stride2offset.h"
#include "stdlib/blas/base/shared.h"
#include "stdlib/ml/base/kmeans/metrics.h"
#include "stdlib/stats/strided/distances/dsquared_euclidean.h"
#include "stdlib/stats/strided/distances/dcorrelation.h"
#include "stdlib/stats/strided/distances/dcosine_distance.h"
#include "stdlib/stats/strided/distances/dcityblock.h"
#include <stdint.h>

/**
* Data type to store distance metric function.
*/
typedef double func_type( const CBLAS_INT N, const double *X, const CBLAS_INT sx, const CBLAS_INT ox, const double *Y, const CBLAS_INT strideY, const CBLAS_INT offsetY );

/**
* Compute inertia between double-precision floating-point centroids and data points.
*
* @param order   storage layout
* @param M       number of data points
* @param N       number of features
* @param metric  distance metric
* @param X       input data matrix
* @param LDX     stride of the first dimension of `X` (a.k.a., leading dimension of the matrix `X`)
* @param C       centroid matrix
* @param LDC     stride of the first dimension of `C` (a.k.a., leading dimension of the matrix `C`)
* @param labels  labels array
* @param sl      stride length for `labels`
*/
double API_SUFFIX(stdlib_strided_dkmeans_compute_inertia)( const CBLAS_LAYOUT order, const CBLAS_INT M, const CBLAS_INT N, const enum STDLIB_ML_KMEANS_METRIC metric, const double *X, const CBLAS_INT LDX, const double *C, const CBLAS_INT LDC, const CBLAS_INT *labels, const CBLAS_INT sl ) {
	CBLAS_INT sx1;
	CBLAS_INT sx2;
	CBLAS_INT sc1;
	CBLAS_INT sc2;
	CBLAS_INT ol;

	if ( order == CblasColMajor ) {
		sx1 = 1;
		sc1 = 1;
		sx2 = LDX;
		sc2 = LDC;
	} else { // order == CblasRowMajor
		sx1 = LDX;
		sc1 = LDC;
		sx2 = 1;
		sc2 = 1;
	}
	ol = stdlib_strided_stride2offset( M, sl );
	return API_SUFFIX(stdlib_strided_dkmeans_compute_inertia_ndarray)( M, N, metric, X, sx1, sx2, 0, C, sc1, sc2, 0, labels, sl, ol );
}

/**
* Compute inertia between double-precision floating-point centroids and data points using alternative indexing semantics.
*
* @param M       number of data points
* @param N       number of features
* @param metric  distance metric
* @param X       input data matrix
* @param sx1     stride of the first dimension of `X`
* @param sx2     stride of the second dimension of `X`
* @param ox      index offset for `X`
* @param C       centroid matrix
* @param sc1     stride of the first dimension of `C`
* @param sc2     stride of the second dimension of `C`
* @param oc      index offset for `C`
* @param labels  labels array
* @param sl      stride length for `labels`
* @param ol      index offset for `labels`
*/
double API_SUFFIX(stdlib_strided_dkmeans_compute_inertia_ndarray)( const CBLAS_INT M, const CBLAS_INT N, const enum STDLIB_ML_KMEANS_METRIC metric, const double *X, const CBLAS_INT sx1, const CBLAS_INT sx2, const CBLAS_INT ox, const double *C, const CBLAS_INT sc1, const CBLAS_INT sc2, const CBLAS_INT oc, const CBLAS_INT *labels, const CBLAS_INT sl, const CBLAS_INT ol ) {
	double inertia;
	CBLAS_INT xidx;
	CBLAS_INT cidx;
	CBLAS_INT lidx;
	func_type *f;
	CBLAS_INT c;
	CBLAS_INT i;
	double d;

	if ( metric == STDLIB_ML_KMEANS_SQEUCLIDEAN ) {
		f = (func_type *) stdlib_strided_dsquared_euclidean_ndarray;
	} else if ( metric == STDLIB_ML_KMEANS_CORRELATION ) {
		f = (func_type *) stdlib_strided_dcorrelation_ndarray;
	} else if ( metric == STDLIB_ML_KMEANS_CITYBLOCK ) {
		f = (func_type *) stdlib_strided_dcityblock_ndarray;
	} else {
		f = (func_type *) stdlib_strided_dcosine_distance_ndarray;
	}

	inertia = 0.0;
	xidx = ox;
	lidx = ol;
	for ( i = 0; i < M; i++ ) {
		c = labels[ lidx ];
		cidx = oc + ( c*sc1 );
		d = f( N, X, sx2, xidx, C, sc2, cidx );
		inertia += d;
		xidx += sx1;
		lidx += sl;
	}
	return inertia;
}
